 function detail(event){let d={};try{d=JSON.parse(event.detail);}catch{}if(event.kind==='gacha.drawn')return d.assetId?(d.duplicate?'Duplikat · ':'Limited baru · ')+(state.catalog.find(i=>i.id===d.assetId)?.name||'Aset'):'Koin kembali '+number(d.payout)+' · bersih '+number(d.net);if(event.kind==='game.completed')return `${d.outcome==='win'?'Menang':'Selesai'} · +${number(d.xp)} XP · ${number(d.seconds)} detik`;if(d.reason)return d.reason;if(d.item)return state.catalog.find(i=>i.id===d.item)?.name||'Kosmetik';if(d.email)return d.email;return event.kind==='preview.created'?'Data demo khusus preview':'—';}
