 function settings(){return heading('AKUNMU, PILIHANMU.','Atur tempatmu.','Nama, keamanan, dan identitas akun.')+`<section class="ac-settings-grid"><div class="ac-panel"><h2>Profil pemain</h2><p class="ac-muted">Nama baru dipakai saat bergabung ke meja berikutnya.</p><form id="ac-profile-form"><label>Nama panggilan<input name="name" value="${esc(state.user.name)}" maxlength="24" required></label><label>Email<input value="${esc(state.user.email)}" readonly></label><button class="ac-btn primary">Simpan profil</button></form><p class="ac-body-note">Email tidak bisa diubah dari browser. Hubungi admin untuk bantuan.</p></div><div class="ac-panel"><h2>Keamanan akun</h2><p class="ac-muted">${state.user.verified?'Identitas Google sudah terverifikasi.':'Hubungkan Google dengan email yang sama untuk memverifikasi akun.'}</p><a class="ac-btn" href="/auth/google?link=1">Hubungkan Google</a><form id="ac-password-form">${passwordField('ac-current-password','current','Password saat ini (bila sudah dibuat)','current-password',false)}${passwordField('ac-new-password','password','Password baru')}${passwordField('ac-new-confirm','confirmPassword','Konfirmasi password')}<button class="ac-btn">Perbarui password</button></form><p class="ac-body-note">Perubahan password mengakhiri sesi perangkat lain. Tidak ada password atau token di audit log.</p></div></section><p><button class="ac-btn" data-action="logout-others">Keluar dari semua perangkat lain</button> <button class="ac-btn danger" data-action="logout">Keluar dari akun ini</button></p>`;}
